function isAnagram(a: string, b: string) {
  if (a.length !== b.length) return false;
  const counts = new Map<string, number>();
  for (const ch of a) counts.set(ch, (counts.get(ch) ?? 0) + 1);
  for (const ch of b) {
    const left = (counts.get(ch) ?? 0) - 1;
    if (left < 0) return false; // b has an extra ch
    counts.set(ch, left);
  }
  return true;
}

function pairForBudget(sizes: number[], budget: number) {
  let l = 0;
  let r = sizes.length - 1;
  while (l < r) {
    const sum = sizes[l] + sizes[r];
    if (sum === budget) return [l, r];
    if (sum < budget) l++; // need more
    else r--;              // too much
  }
  return null;
}

function busiestRun(tokens: number[], k: number) {
  let sum = 0;
  for (let i = 0; i < k; i++) sum += tokens[i];
  let best = sum;
  for (let i = k; i < tokens.length; i++) {
    sum += tokens[i] - tokens[i - k]; // add new, drop old
    best = Math.max(best, sum);
  }
  return best;
}

function longestUnique(s: string) {
  const lastSeen = new Map<string, number>();
  let start = 0;
  let best = 0;
  for (let i = 0; i < s.length; i++) {
    const prev = lastSeen.get(s[i]);
    // repeat inside the window: shrink past it
    if (prev !== undefined && prev >= start) start = prev + 1;
    lastSeen.set(s[i], i);
    best = Math.max(best, i - start + 1);
  }
  return best;
}
